      if (documents.get(mechanism.anchor.document) !== "indenture") context.addIssue({code: "custom", path: [...path, "anchor"], message: `${series.id}: mechanism ${mechanism.mechanism} must cite an indenture, not ${mechanism.anchor.document}`});
